import {ChartCard} from '@github-ui/chart-card'
import {Blankslate} from '@primer/react/experimental'
import styles from './Traffic.module.css'
import {GraphIcon} from '@primer/octicons-react'
import {clsx} from 'clsx'

interface TrafficGraphProps {
  title: string
  description: string
  chartData: Array<{name: string; data: number[]}>
  categories: string[]
  yAxisTitle: string
  tickInterval?: number
  maxValue?: number
  yAxisTickCount?: number
}

export function TrafficGraph({
  title,
  description,
  chartData,
  categories,
  yAxisTitle,
  tickInterval,
  maxValue,
  yAxisTickCount,
}: TrafficGraphProps) {
  const hasValidChartStructure =
    Array.isArray(chartData) &&
    chartData.length > 0 &&
    chartData.every(series => Array.isArray(series.data)) &&
    Array.isArray(categories) &&
    categories.length > 0

  if (!hasValidChartStructure) {
    const sectionClasses = clsx(styles.bottomSectionColumn, 'tmp-pb-6')
    return (
      <div className={sectionClasses}>
        <h3 className="f4 text-semibold mb-2" data-hpc>
          {title}
        </h3>
        <div className="tmp-mt-3">
          <Blankslate border>
            <Blankslate.Visual>
              <GraphIcon size="medium" />
            </Blankslate.Visual>
            <Blankslate.Heading as="h4" className="mb-2 f5">
              No data to show for this period.
            </Blankslate.Heading>
          </Blankslate>
        </div>
      </div>
    )
  }

  const allValues = chartData.flatMap(d => d.data)
  const rawMaxValue = maxValue !== undefined ? maxValue : allValues.length > 0 ? Math.max(...allValues) : 0
  // Max value of 1 keeps the zero line at the bottom of the chart next to the X axis instead of rendering it in the middle.
  const newMaxValue = rawMaxValue > 0 ? rawMaxValue : 1
  const calculatedTickInterval = (() => {
    if (typeof yAxisTickCount === 'number' && newMaxValue && yAxisTickCount > 1) {
      return Math.ceil(newMaxValue / (yAxisTickCount - 1))
    }
    return tickInterval
  })()

  return (
    <div className="flex-1 min-width-0">
      <ChartCard size="medium">
        <ChartCard.Title as="h3">{title}</ChartCard.Title>
        <ChartCard.Description>{description}</ChartCard.Description>
        <ChartCard.LineChart
          series={chartData}
          options={{
            xAxis: {
              categories,
              title: '',
              labels: {
                style: {
                  fontSize: 'var(--text-caption-size)',
                  fontFamily: 'var(--fontStack-system)',
                },
                rotation: 0,
              },
              gridLineWidth: 1,
              gridLineColor: 'var(--borderColor-default)',
              tickInterval: 2,
              minorGridLineWidth: 0,
              tickmarkPlacement: 'on',
              startOnTick: false,
              endOnTick: true,
              showLastLabel: false,
              max: categories.length - 1,
            },
            yAxis: {
              title: yAxisTitle,
              labels: {
                style: {
                  fontSize: 'var(--text-caption-size)',
                  fontFamily: 'var(--fontStack-system)',
                },
              },
              gridLineWidth: 1,
              gridLineColor: 'var(--borderColor-default)',
              min: 0,
              max: newMaxValue,
              tickInterval: calculatedTickInterval,
              startOnTick: true,
              endOnTick: true,
            },
            plot: {
              pointPlacement: 'on',
            },
          }}
          overrideOptionsNotRecommended={{
            chart: {
              marginRight: 15,
              marginTop: 15,
            },
          }}
        />
      </ChartCard>
    </div>
  )
}
