import {useCallback} from 'react'
import {Blankslate} from '@primer/react/experimental'
import {TrafficGraph} from './TrafficGraph'
import {LoadingState} from './TrafficLoading'
import {TrafficError} from './TrafficError'
import styles from './Traffic.module.css'
import type {TrafficChartData} from '../utils/transform-traffic-data'

interface RealTrafficGraphProps {
  title: string
  yAxisTitle: string
  data: TrafficChartData | undefined
  loading: boolean
  error: string | undefined
}

/**
 * Simplified traffic graph component with sensible defaults
 */
export function RealTrafficGraph({data: chartData, loading, error, title, yAxisTitle}: RealTrafficGraphProps) {
  // Generate description from chart data if not provided
  const getDescription = useCallback(() => {
    if (!chartData?.summary) return ''
    const summaryTotal = chartData.summary?.total ?? 0
    const summaryUnique = chartData.summary?.unique ?? 0

    if (title.toLowerCase().includes('unique')) {
      if (title.toLowerCase().includes('cloner')) {
        return `${summaryUnique.toLocaleString()} Unique cloners`
      } else if (title.toLowerCase().includes('visitor')) {
        return `${summaryUnique.toLocaleString()} Unique visitors`
      }
      return `${summaryUnique.toLocaleString()} Unique`
    } else {
      if (title.toLowerCase().includes('clone')) {
        return `${summaryTotal.toLocaleString()} Clones`
      } else if (title.toLowerCase().includes('view')) {
        return `${summaryTotal.toLocaleString()} Views`
      }
      return `${summaryTotal.toLocaleString()} Total`
    }
  }, [chartData, title])

  if (loading) {
    return (
      <div className={`flex-1 min-width-0 ${styles.containerHeight}`}>
        <LoadingState />
      </div>
    )
  }

  if (error) {
    return (
      <div className={`flex-1 min-width-0 ${styles.containerHeight}`}>
        <TrafficError error={error} />
      </div>
    )
  }

  if (!chartData || chartData.chartData.length === 0) {
    return (
      <div className={`flex-1 min-width-0 ${styles.containerHeight}`}>
        <Blankslate>
          <p>No traffic data available for this period</p>
        </Blankslate>
      </div>
    )
  }

  return (
    <TrafficGraph
      title={title}
      description={getDescription()}
      chartData={chartData.chartData}
      categories={chartData.categories}
      yAxisTitle={yAxisTitle}
      maxValue={chartData.maxValue}
      yAxisTickCount={5}
    />
  )
}
