import {TrafficDataTable} from '../TrafficDataTable'
import {Link, Truncate} from '@primer/react'
import {clsx} from 'clsx'
import styles from '../Traffic.module.css'
import type {TrafficDataItem} from '../../hooks/traffic-types'

interface Props {
  data: TrafficDataItem[] | undefined
  isLoading: boolean
  error: string | undefined
}

export function ContentTrafficTable({data, isLoading, error}: Props) {
  const hasData = Array.isArray(data) && data.length > 0 && data.some(item => item.views > 0 || item.uniqueVisitors > 0)

  return (
    <div className={clsx(styles.bottomSectionColumn, 'tmp-pb-6')}>
      <TrafficDataTable
        title="Popular content"
        data={hasData ? data : []}
        isLoading={isLoading}
        error={error}
        columns={[
          {
            header: 'Content',
            field: 'site',
            rowHeader: true,
            renderCell: item => <TableCell item={item} />,
          },
          {
            header: 'Views',
            field: 'views',
          },
          {
            header: 'Unique Visitors',
            field: 'uniqueVisitors',
          },
        ]}
        emptyMessage="No popular content data available for this period"
        ariaLabelledBy="popular-content"
      />
    </div>
  )
}

interface TableCellProps {
  item: TrafficDataItem
}
function TableCell({item}: TableCellProps) {
  const siteValue = item.site

  // For popular content, use the path for linking but show the title
  const displayTitle = item.title || siteValue || 'Unknown'
  const linkPath = item.path || siteValue

  if (linkPath && linkPath !== 'Unknown' && !linkPath.includes('unknown-')) {
    return (
      <Link href={linkPath} target="_blank" rel="noopener noreferrer">
        <Truncate title={displayTitle} maxWidth="200px" inline>
          {displayTitle}
        </Truncate>
      </Link>
    )
  }
  return (
    <Truncate title={displayTitle} maxWidth="200px" inline>
      {displayTitle}
    </Truncate>
  )
}
